package pz.escapefromzomboidfirearms.zb;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import zombie.gameStates.ChooseGameInfo;

/** Original mechanical tracks, generated by tools/moving_weapon_parts.py. No game writes. */
public final class MovingWeaponPartsData {
    static final String RESOURCE = "media/viewpoint/TW_MovingWeaponParts.bin";
    private static boolean attempted;
    private static MovingWeaponPartsData cached;
    static String status = "not loaded";
    final Map<String, Weapon> weapons = new LinkedHashMap<>(), byTpl = new LinkedHashMap<>();
    final Map<String, Map<String, Track>> families = new LinkedHashMap<>();
    /** Every family holding a track name: a REFERENCE_TRANSFER weapon's hands play another family's clip (wave 1488). */
    final Map<String, List<String>> owners = new HashMap<>();
    /**
     * A family's own check clip kept under the transferred clip's name, where the hands' clip leaves this family's
     * opening parts still (tools/moving_weapon_parts.py chamberCheckAliases). Its family's own lookup only: an alias
     * never makes a family an owner of the hands' clip.
     */
    final Map<String, Map<String, String>> aliases = new HashMap<>();
    /** Each family's first weapon by key: the node frames its clips' bone deltas are measured in. */
    final Map<String, Weapon> references = new HashMap<>();

    record Node(String name, String model, double[] bind) { }
    record Weapon(String key, String tpl, String family, int flags, double rpm, Map<String, Node> nodes,
                  Map<String, String> slots, String body) {
        boolean boltCatch() { return (flags & 1) != 0; }
        boolean pump() { return (flags & 4) != 0; }
    }

    static final class Track {
        /** A track that never leaves its idle: no bone moves more than this (model units, 0.17 mm) or turns more than STATIC_TURN. */
        static final double STATIC_TRAVEL = 1e-4, STATIC_TURN = Math.toRadians(.5);
        final String name;
        final double seconds;
        final Map<String, float[]> bones;
        private double motion = -1;
        private int moving = -1;

        Track(String name, double seconds, Map<String, float[]> bones) {
            this.name = name; this.seconds = seconds; this.bones = bones;
        }

        double[] sample(String bone, double u) {
            if (bone == null || !Double.isFinite(u)) return null;
            float[] f = bones.get(bone);
            if (f == null) return null;
            int n = f.length / 12;
            double x = Math.max(0, Math.min(1, u)) * (n - 1);
            int a = Math.min((int) x, n - 1), b = Math.min(a + 1, n - 1);
            return FpPose.interp(frame(f, a), frame(f, b), x - a);
        }

        static double[] frame(float[] f, int k) {
            double[] m = new double[16];
            for (int i = 0; i < 12; i++) m[i] = f[k * 12 + i];
            m[15] = 1;
            return m;
        }

        /** A bone's largest translation from its idle over the clip (model units); 0 without the bone. */
        double travel(String bone) {
            float[] f = bone == null ? null : bones.get(bone);
            double most = 0;
            if (f != null) for (int k = 0; k < f.length / 12; k++) most = Math.max(most, length(f, k));
            return most;
        }

        /** The share of a bone's largest translation that lies along its own Y axis (the bore for a chamber node); 0 without one. */
        double axialShare(String bone) {
            float[] f = bone == null ? null : bones.get(bone);
            if (f == null) return 0;
            int at = 0;
            for (int k = 1; k < f.length / 12; k++) if (length(f, k) > length(f, at)) at = k;
            double most = length(f, at);
            return most > 0 ? Math.abs(f[at * 12 + 7]) / most : 0;
        }

        /** How far a bone ends from where the clip starts it, and its nearest approach to its idle (model units); infinite without it. */
        double[] returnAndNearest(String bone) {
            float[] f = bone == null ? null : bones.get(bone);
            if (f == null) return new double[] {Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY};
            int last = (f.length / 12 - 1) * 12;
            double dx = f[last + 3] - f[3], dy = f[last + 7] - f[7], dz = f[last + 11] - f[11], least = Double.POSITIVE_INFINITY;
            for (int k = 0; k < f.length / 12; k++) least = Math.min(least, length(f, k));
            return new double[] {Math.sqrt(dx * dx + dy * dy + dz * dz), least};
        }

        /** A bone's translation from its idle at the clip's first frame (model units); infinite without the bone. */
        double start(String bone) {
            float[] f = bone == null ? null : bones.get(bone);
            return f == null ? Double.POSITIVE_INFINITY : length(f, 0);
        }

        /** The largest translation any bone reaches (model units). */
        double motion() {
            if (motion < 0) {
                double most = 0;
                for (String bone : bones.keySet()) most = Math.max(most, travel(bone));
                motion = most;
            }
            return motion;
        }

        /** Some bone leaves its idle (an override clip whose curves do not bind to the rig stays still). */
        boolean moving() {
            if (moving < 0) {
                boolean any = false;
                for (float[] f : bones.values()) {
                    for (int k = 0; k < f.length / 12 && !any; k++) {
                        double trace = (f[k * 12] + f[k * 12 + 5] + f[k * 12 + 10] - 1) / 2;
                        any = length(f, k) > STATIC_TRAVEL || Math.acos(Math.max(-1, Math.min(1, trace))) > STATIC_TURN;
                    }
                    if (any) break;
                }
                moving = any ? 1 : 0;
            }
            return moving == 1;
        }

        private static double length(float[] f, int k) {
            double x = f[k * 12 + 3], y = f[k * 12 + 7], z = f[k * 12 + 11];
            return Math.sqrt(x * x + y * y + z * z);
        }
    }

    static synchronized MovingWeaponPartsData get() {
        if (!attempted) {
            attempted = true;
            try {
                ChooseGameInfo.Mod mod = ChooseGameInfo.getModDetails("EscapeFromZomboidFirearms");
                if (mod == null) throw new IOException("mod directory unavailable");
                for (String root : new String[] {mod.getVersionDir(), mod.getCommonDir(), mod.getDir()}) {
                    if (root != null && !root.isBlank() && Files.isRegularFile(Path.of(root).resolve(RESOURCE))) {
                        cached = load(Path.of(root).resolve(RESOURCE));
                        break;
                    }
                }
                if (cached == null) throw new IOException(status.equals("not loaded") ? "resource missing" : status);
            } catch (Throwable e) { status = "refused: " + e; }
        }
        return cached;
    }

    /** Explicit file entry for the native offline parser checks. A failure never reaches a frame. */
    public static MovingWeaponPartsData load(Path path) {
        try {
            long size = Files.size(path);
            if (size < 24 || size > 128 * 1024 * 1024) throw new IOException("resource size " + size);
            MovingWeaponPartsData result = parse(ByteBuffer.wrap(Files.readAllBytes(path)).order(ByteOrder.LITTLE_ENDIAN));
            status = "loaded " + result.weapons.size() + " weapons, " + result.families.size() + " families";
            return result;
        } catch (Exception | LinkageError e) { status = "refused: " + e; return null; }
    }

    static MovingWeaponPartsData parse(ByteBuffer b) throws IOException {
        byte[] magic = new byte[8]; b.get(magic);
        if (!Arrays.equals(magic, "TWMOVEP1".getBytes(StandardCharsets.US_ASCII)) || b.getInt() != 3 || b.getInt() != 30) {
            throw new IOException("resource header");
        }
        MovingWeaponPartsData d = new MovingWeaponPartsData();
        int count = count(b, 4096);
        for (int k = 0; k < count; k++) {
            String key = text(b), tpl = text(b), family = text(b);
            int flags = b.getInt();
            double rpm = finite(b.getFloat());
            if (rpm < 0 || rpm > 10000) throw new IOException("weapon rate");
            if ((flags & ~7) != 0 || !tpl.matches("[a-f0-9]{24}")) throw new IOException("weapon identity/flags");
            Map<String, Node> nodes = new LinkedHashMap<>();
            int nn = count(b, 128);
            for (int n = 0; n < nn; n++) {
                String name = text(b), model = text(b);
                double[] m = new double[16];
                for (int i = 0; i < 12; i++) m[i] = finite(b.getFloat());
                m[15] = 1;
                if (Math.abs(det(m)) < 1e-8 || nodes.put(name, new Node(name, model, m)) != null) throw new IOException("node " + name);
            }
            Map<String, String> slots = new LinkedHashMap<>();
            int ns = count(b, 256);
            for (int n = 0; n < ns; n++) {
                String slot = text(b), bone = text(b);
                if (!nodes.containsKey(bone) || slots.put(slot, bone) != null) throw new IOException("slot " + slot);
            }
            Weapon w = new Weapon(key, tpl, family, flags, rpm, Map.copyOf(nodes), Map.copyOf(slots), text(b));
            if (d.weapons.put(key, w) != null || d.byTpl.put(tpl, w) != null) throw new IOException("duplicate weapon");
        }
        int nf = count(b, 1024);
        for (int k = 0; k < nf; k++) {
            String family = text(b);
            Map<String, Track> tracks = new LinkedHashMap<>();
            int nt = count(b, 2048);
            for (int t = 0; t < nt; t++) {
                String name = text(b);
                double seconds = finite(b.getFloat());
                if (seconds <= 0 || seconds > 120) throw new IOException("track duration");
                int nb = count(b, 128);
                Map<String, float[]> bones = new LinkedHashMap<>();
                for (int n = 0; n < nb; n++) {
                    String bone = text(b);
                    int frames = count(b, 8192);
                    if (frames < 2 || (long) frames * 48 > b.remaining()) throw new IOException("track frames");
                    float[] f = new float[frames * 12];
                    for (int i = 0; i < f.length; i++) f[i] = finite(b.getFloat());
                    for (int i = 0; i < frames; i++) {
                        double[] m = Track.frame(f, i);
                        if (Math.abs(det(m) - 1) > .003) throw new IOException("track rotation " + name + "/" + bone);
                        for (int a = 0; a < 3; a++) for (int c = 0; c < 3; c++) {
                            double dot = 0;
                            for (int r = 0; r < 3; r++) dot += m[r * 4 + a] * m[r * 4 + c];
                            if (Math.abs(dot - (a == c ? 1 : 0)) > .003) throw new IOException("non-rigid track " + name);
                        }
                    }
                    if (bones.put(bone, f) != null) throw new IOException("duplicate bone");
                }
                if (tracks.put(name, new Track(name, seconds, Map.copyOf(bones))) != null) throw new IOException("duplicate track");
            }
            Map<String, String> aliased = new LinkedHashMap<>();
            int na = count(b, 256);
            for (int a = 0; a < na; a++) {
                String name = text(b), target = text(b);
                if (tracks.containsKey(name) || !tracks.containsKey(target) || aliased.put(name, target) != null) throw new IOException("alias " + name);
            }
            if (!aliased.isEmpty()) d.aliases.put(family, Map.copyOf(aliased));
            if (d.families.put(family, Map.copyOf(tracks)) != null) throw new IOException("duplicate family");
        }
        if (b.hasRemaining()) throw new IOException("trailing bytes");
        for (var e : d.families.entrySet()) {
            for (String name : e.getValue().keySet()) d.owners.computeIfAbsent(name, k -> new ArrayList<>()).add(e.getKey());
        }
        for (Weapon w : d.weapons.values()) d.references.putIfAbsent(w.family(), w);
        return d;
    }

    static double det(double[] m) {
        return m[0] * (m[5] * m[10] - m[6] * m[9]) - m[1] * (m[4] * m[10] - m[6] * m[8])
                + m[2] * (m[4] * m[9] - m[5] * m[8]);
    }

    private static int count(ByteBuffer b, int limit) throws IOException {
        int n = b.getInt();
        if (n < 0 || n > limit) throw new IOException("count " + n);
        return n;
    }

    private static String text(ByteBuffer b) throws IOException {
        int n = b.getShort() & 65535;
        if (n == 0) return "";
        if (n > 4096 || n > b.remaining()) throw new IOException("text size");
        byte[] s = new byte[n]; b.get(s);
        String value = new String(s, StandardCharsets.UTF_8);
        if (!Arrays.equals(s, value.getBytes(StandardCharsets.UTF_8)) || value.indexOf('\0') >= 0) throw new IOException("text encoding");
        return value;
    }

    private static float finite(float f) throws IOException {
        if (!Float.isFinite(f)) throw new IOException("non-finite");
        return f;
    }
}
